// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    TokenBank bank;

    function setUp() public { c = new ModifierEntrancy(); bank = new TokenBank(); }

    function testFuzz_property(address actor, uint256 seed) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        // msg.sender must return the matching token hash, so route through the helper
        vm.prank(address(bank));
        try c.airDrop() {
            // General rule: a successful airdrop credits exactly 20 tokens
            assertTrue(c.tokenBalance(address(bank)) == 20, "airdrop must credit exactly 20 tokens");
        } catch {
            // reverting path keeps balance at zero
            assertTrue(c.tokenBalance(address(bank)) == 0, "failed airdrop must not credit tokens");
        }
    }
}

contract TokenBank {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}
